cb := gobreaker.NewCircuitBreaker(gobreaker.Settings{
	Name:        "payments",
	MaxRequests: 1,               // probes allowed in Half-Open
	Timeout:     5 * time.Second, // cooldown before Half-Open
	ReadyToTrip: func(c gobreaker.Counts) bool {
		if c.Requests < 20 { // require a minimum sample size
			return false
		}
		return float64(c.TotalFailures)/float64(c.Requests) >= 0.5
	},
})

body, err := cb.Execute(func() (any, error) {
	return fetchCharge(ctx) // the protected call
})
if errors.Is(err, gobreaker.ErrOpenState) {
	return cachedFallback() // breaker open -> serve a fallback
}
_ = body
